#include "ckks_narrow_basis_benchmark.hpp"
#include <iostream>
int main(){
TFHEpp::CKKSSeed a{UINT64_C(1),UINT64_C(2),UINT64_C(3),UINT64_C(4)};
TFHEpp::CKKSSeed b{UINT64_C(5),UINT64_C(6),UINT64_C(7),UINT64_C(3599532394160262945)};
if(a==b)return 1; TFHEpp::ckks_detail::CKKSSeedStream x(a),y(b); for(int i=0;i<16384;++i)if(x.next()!=y.next())return 2; std::cout<<"Distinct seeds produce identical 16384-word streams\n"; }
